def safe_relative(name):
    require(isinstance(name, str) and name and "\\" not in name and "\0" not in name, "Invalid member name")
    path = PurePosixPath(name)
    require(not path.is_absolute() and path.as_posix() == name and all(part not in ("", ".", "..", ".git", "node_modules", ".aws", ".codex", ".agents") for part in path.parts), "Unsafe relative path")
    return path


def safe_member(name):
    path = safe_relative(name)
    require(name in SOURCE24_ALLOWED_MEMBERS and len(path.parts) >= 2 and path.parts[0] in ("workspace", "temporary"), "Destination outside the exact Source24 selection")
    return path.parts[0], PurePosixPath(*path.parts[1:])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--manifest-sha256", required=True)
    parser.add_argument("--archive", type=Path, required=True)
    parser.add_argument("--base-manifest", type=Path, required=True)
    parser.add_argument("--workspace", type=Path, default=Path("/workspace"))
    parser.add_argument("--temporary-root", type=Path, default=Path("/tmp"))
    parser.add_argument("--restore", action="store_true")
    args = parser.parse_args()
    require(isinstance(EXPECTED_INDEX_SHA256, str) and len(EXPECTED_INDEX_SHA256) == 64 and isinstance(EXPECTED_ARCHIVE_SHA256, str) and len(EXPECTED_ARCHIVE_SHA256) == 64 and all(type(v) is int for v in (EXPECTED_ARCHIVE_BYTES, EXPECTED_FILE_COUNT, EXPECTED_LOGICAL_BYTES, EXPECTED_TAR_BYTES)), "UNSEALED Source24 template: Root must bind the actual verified final archive/index")
    raw_manifest, _ = regular_bytes(args.manifest, 4 * 1024 * 1024)
    require(args.manifest_sha256 == EXPECTED_INDEX_SHA256 and digest(raw_manifest) == EXPECTED_INDEX_SHA256, "Pinned Source24 index differs")
    manifest = json.loads(raw_manifest)
    require(manifest["schemaVersion"] == 1 and manifest["regularFilesOnly"] is True and manifest["baseManifestSha256"] == EXPECTED_BASE_INDEX_SHA256, "Unsupported Source24 index/base")
    require(manifest["requiredExistingBaseFiles"] == REQUIRED_BASE_FILES, "Exact210 required base rows differ")
    base_bytes, _ = regular_bytes(args.base_manifest, 4 * 1024 * 1024)
    require(digest(base_bytes) == EXPECTED_BASE_INDEX_SHA256, "Preserved333 base index differs")
    base = json.loads(base_bytes)
    require(base["fileCount"] == 333 and base["regularFilesOnly"] is True, "Required333 base schema differs")
    base_rows = {row["path"]: row for row in base["files"]}
    roots = {"workspace": args.workspace.absolute(), "temporary": args.temporary_root.absolute()}
    require(roots["workspace"] != roots["temporary"] and roots["workspace"] not in roots["temporary"].parents and roots["temporary"] not in roots["workspace"].parents, "Two distinct nonoverlapping roots required")
    root_fds = {key: directory_fd(path) for key, path in roots.items()}
    try:
        # Old333 restoration is performed by its own pinned restorer. Never recreate or overwrite its files here.
        for row in REQUIRED_BASE_FILES:
            name = safe_relative(row["path"])
            require(row["path"] in base_rows and all(row[key] == base_rows[row["path"]][key] for key in ("sha256", "bytes", "mode")), "Base row differs")
            parent = directory_fd(name.parent, root_fd=root_fds["workspace"])
            try:
                data, mode = regular_bytes(roots["workspace"] / name, row["bytes"], parent)
                require(len(data) == row["bytes"] and digest(data) == row["sha256"] and mode == row["mode"], "Required old333 Source/data missing or changed; restore it first")
            finally:
                os.close(parent)
        raw_archive, _ = regular_bytes(args.archive)
        require(len(raw_archive) == EXPECTED_ARCHIVE_BYTES == manifest["archive"]["bytes"] and digest(raw_archive) == EXPECTED_ARCHIVE_SHA256 == manifest["archive"]["sha256"], "Pinned archive differs")
        rows = manifest["files"]
        require(isinstance(rows, list) and len(rows) == EXPECTED_FILE_COUNT <= 512, "Finite exact Source24 index required")
        expected = {}
        for row in rows:
            key, relative = safe_member(row["path"])
            require(row["path"] not in expected, "Duplicate destination")
            require(type(row["bytes"]) is int and 0 <= row["bytes"] <= 16 * 1024 * 1024 and type(row["mode"]) is int and row["mode"] in (0o444, 0o600, 0o644, 0o700, 0o755), "Invalid finite regular member")
            expected[row["path"]] = row
        require(set(expected) == SOURCE24_ALLOWED_MEMBERS, "Exact Source24 allowlist differs")
        for name in expected:
            require(not any(parent.as_posix() in expected for parent in PurePosixPath(name).parents), "File/directory prefix collision")
        require(sum(row["bytes"] for row in rows) == EXPECTED_LOGICAL_BYTES <= 256 * 1024 * 1024, "Logical bound differs")
        require(manifest["expandedTarBytes"] == EXPECTED_TAR_BYTES <= EXPECTED_LOGICAL_BYTES + EXPECTED_FILE_COUNT * 4096 + 20480, "Finite PAX bound differs")
        with gzip.GzipFile(fileobj=io.BytesIO(raw_archive), mode="rb") as compressed:
            raw_tar = compressed.read(EXPECTED_TAR_BYTES + 1)
        require(len(raw_tar) == EXPECTED_TAR_BYTES, "Expanded tar byte count differs")
        payloads = {}
        with tarfile.open(fileobj=io.BytesIO(raw_tar), mode="r:") as archive:
            for member in archive:
                require(len(payloads) < len(expected), "Excess header inventory")
                safe_member(member.name)
                require(set(member.pax_headers) <= {"path"} and member.isreg() and not member.linkname and member.name not in payloads, "Only exact unique regular payloads permitted")
                row = expected[member.name]
                require(member.size == row["bytes"] and member.mode == row["mode"], "Member size/mode differs")
                stream = archive.extractfile(member)
                require(stream is not None, "Missing regular payload")
                data = stream.read(row["bytes"] + 1)
                require(len(data) == row["bytes"] and digest(data) == row["sha256"], "Member hash differs")
                payloads[member.name] = data
        require(len(payloads) == len(expected), "Archive/index inventory differs")
        plan = []
        present = 0
        for name, row in expected.items():
            key, relative = safe_member(name)
            destination = roots[key] / relative
            try:
                parent = directory_fd(relative.parent, root_fd=root_fds[key])
            except FileNotFoundError:
                plan.append((key, relative, row, payloads[name]))
                continue
            try:
                try:
                    data, mode = regular_bytes(destination, row["bytes"], parent)
                except FileNotFoundError:
                    plan.append((key, relative, row, payloads[name]))
                    continue
                require(len(data) == row["bytes"] and digest(data) == row["sha256"] and mode == row["mode"], "Existing differing destination refused: " + str(destination))
                present += 1
            finally:
                os.close(parent)
        # Validate every input, payload and collision before creating any Source24 file.
        created = 0
        if args.restore:
            for key, relative, row, data in plan:
                destination = roots[key] / relative
                parent = directory_fd(relative.parent, create=True, root_fd=root_fds[key])
                try:
                    temporary = ".g350-source24-source-data-" + secrets.token_hex(16)
                    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=parent)
                    try:
                        with os.fdopen(descriptor, "wb") as target:
                            target.write(data); target.flush(); os.fchmod(target.fileno(), row["mode"]); os.fsync(target.fileno())
                        staged, mode = regular_bytes(Path(temporary), row["bytes"], parent)
                        require(digest(staged) == row["sha256"] and mode == row["mode"], "Staged payload differs")
                        os.link(temporary, destination.name, src_dir_fd=parent, dst_dir_fd=parent, follow_symlinks=False)
                        os.fsync(parent)
                        written, mode = regular_bytes(destination, row["bytes"], parent)
                        require(digest(written) == row["sha256"] and mode == row["mode"], "Written payload differs")
                        created += 1
                    finally:
                        os.unlink(temporary, dir_fd=parent)
                finally:
                    os.close(parent)
        print(json.dumps({"archiveVerified": True, "memberCount": len(expected), "existingExactFiles": present, "absentFiles": len(plan), "createdFiles": created, "restoreRequested": args.restore, "requiredPreserved333FilesVerified": len(REQUIRED_BASE_FILES), "exactRootAliases": list(roots), "symlinksRestored": 0, "exclusiveAtomicPublication": True, "runtimeImports": 0, "sdkOrRuntimeReconstructed": False, "RootAuthorityOrNonceRestored": False, "BoundManifestRestored": False, "historicalReceiptsConferNoAuthority": True, "operationalClosureQualified": False, "accepted49": False, "fabricationReady": False}))
    finally:
        for descriptor in root_fds.values():
            os.close(descriptor)


if __name__ == "__main__":
    main()
